import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"離下離上 離：","description":"京氏易傳 - 離下離上 離：","frontmatter":{"title":"離下離上 離：","description":"京氏易傳 - 離下離上 離："},"headers":[],"relativePath":"classics/jingshi/050.md","filePath":"classics/jingshi/050.md"}'),i={name:"classics/jingshi/050.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"離下離上-離",tabindex:"-1"},[l("離下離上 離： "),e("a",{class:"header-anchor",href:"#離下離上-離","aria-label":"Permalink to “離下離上 離：”"},"​")],-1),e("p",null,"本於純陽，陰氣貫中，稟於剛健，見乎文明。故《易》曰：“君子以繼明照於四方”。（虎易注：此句出於象辭，原句為：“象曰：明兩作，離，大人以繼明照於四方。”其中的“君子”當為“大人”之誤。）【離卦中虛，始於乾象。純則健，不能柔明，故以北方陰氣貫中，柔剛而文明也。】陽為陰主，陽伏於陰也。【成卦義在六五。】是以體離，為日為火，始於陽象而假以陰氣。純用剛健，不能明照，故以陰氣入陽，柔於剛健而能順柔，中虛見火象也。【是以離取中虛，氣炎方能照物，日昌火，本陽象也。純以陰，又不能乾於物，純以陽，又暴於物，故取陰柔於中女，能成於物也。】與坎為飛伏。【己巳火，戊子土。】（虎易注：戊子土當為戊子水之誤。）宗廟為世，應上見三公。【上九，九三。】",-1),e("p",null,"建始戊申至癸丑，【立秋至大寒。】積算起癸丑至壬子，【火取胎月至本月。】週而復始。土水二象入離火位，【土水二位入卦起算。】",-1),e("p",null,"五星從位起歲星，【木星入火宮卦。】室宿從位降己巳火，【二十八宿，分室宿入離宮上九己巳火上也。】分氣候三十六。【積算起數三十六，立位定吉凶。】",-1),e("p",null,"內外二象，配於火土為祥。【土火入離為祥。】互見悅順，著於明麗。【兌巽二象。】",-1),e("p",null,"陰陽升降入初九，適變從陰，止於艮象。【內卦變也。】吉凶從位，起至六五，休廢在何爻。【看當何位金水木火土，與本宮刑宮。】次降入火山旅卦。【初九爻變之。】",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
